import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

const LanguagePage = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const [searchType, setSearchType] = useState('partial');
  const [sourceFilter, setSourceFilter] = useState('all');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState({ total: 0, tesoro: 0, dialecto: 0 });

  // Mock data - in a real app, this would be loaded from your JSON files
  const mockData = [
    {
      letter: 'A',
      term: 'A',
      es_definitions: [
        'Símbolo de la calificación recibida en un curso, examen o cualquier otro tipo de trabajo cuyo valor en términos numéricos oscila entre 3.5 y 4.0, ó entre 90 y 100.',
        'Calificación académica máxima.'
      ],
      en_definitions: [
        'Symbol of the qualification received in a course, exam or any other type of work whose value in numerical terms ranges between 3.5 and 4.0, or between 90 and 100.',
        'Top academic qualification.'
      ],
      file_source: 'Tesoro',
      has_overlap: false
    },
    {
      letter: 'C',
      term: 'chavos',
      es_definitions: [
        'Dinero en efectivo.',
        'Monedas de poco valor.'
      ],
      en_definitions: [
        'Cash money.',
        'Low-value coins.'
      ],
      file_source: 'Dialecto',
      has_overlap: true
    },
    {
      letter: 'F',
      term: 'fuego',
      es_definitions: [
        'Algo muy bueno, excelente.',
        'Expresión de aprobación.'
      ],
      en_definitions: [
        'Something very good, excellent.',
        'Expression of approval.'
      ],
      file_source: 'Dialecto',
      has_overlap: false
    }
  ];

  useEffect(() => {
    setResults(mockData);
    setStats({
      total: mockData.length,
      tesoro: mockData.filter(item => item.file_source === 'Tesoro').length,
      dialecto: mockData.filter(item => item.file_source === 'Dialecto').length
    });
  }, []);

  const handleSearch = () => {
    setLoading(true);

    setTimeout(() => {
      let filteredResults = mockData;

      // Apply source filter
      if (sourceFilter !== 'all') {
        if (sourceFilter === 'tesoro') {
          filteredResults = filteredResults.filter(item => item.file_source === 'Tesoro');
        } else if (sourceFilter === 'dialecto') {
          filteredResults = filteredResults.filter(item => item.file_source === 'Dialecto');
        } else if (sourceFilter === 'overlap') {
          filteredResults = filteredResults.filter(item => item.has_overlap);
        }
      }

      // Apply search query
      if (searchQuery.trim()) {
        const query = searchQuery.toLowerCase();
        filteredResults = filteredResults.filter(item => {
          const term = item.term.toLowerCase();
          const esText = item.es_definitions.join(' ').toLowerCase();
          const enText = item.en_definitions.join(' ').toLowerCase();

          switch (searchType) {
            case 'exact':
              return term === query;
            case 'partial':
              return term.includes(query);
            case 'contains':
              return term.includes(query) || esText.includes(query) || enText.includes(query);
            default:
              return term.includes(query);
          }
        });
      }

      setResults(filteredResults);
      setLoading(false);
    }, 500);
  };

  const handleClear = () => {
    setSearchQuery('');
    setResults(mockData);
  };

  const createDefinitionCard = (item, index) => {
    const sourceClass = item.file_source === 'Tesoro' ? 'tesoro' : 'dialecto';
    const badgeClass = item.file_source === 'Tesoro' ? 'badge-tesoro' : 'badge-dialecto';

    return (
      <div key={index} className={`definition-card ${sourceClass}`}>
        <div className="term-title">
          {item.term}
          {item.has_overlap && (
            <span title="This term appears in both sources" style={{ color: '#ffc107' }}>
              🔄
            </span>
          )}
        </div>

        <span className={`source-badge ${badgeClass}`}>{item.file_source}</span>

        <div className="definition-section">
          <h5>🇪🇸 Español:</h5>
          <div className="spanish-def">
            {item.es_definitions.map((def, idx) => (
              <div key={idx}>{def}</div>
            ))}
          </div>
        </div>

        <div className="definition-section">
          <h5>🇺🇸 English:</h5>
          <div className="english-def">
            {item.en_definitions.map((def, idx) => (
              <div key={idx}>{def}</div>
            ))}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="container">
      <Link to="/" className="back-button">
        <i className="fas fa-arrow-left"></i> Back to Home
      </Link>

      <div className="page-content">
        <div className="page-header">
          <h2>📖 Language & Words</h2>
          <p>Explore Puerto Rican Spanish words, phrases, and expressions from multiple sources.</p>
        </div>

        {/* Search Section */}
        <div className="search-section">
          <div className="search-form">
            <input
              type="text"
              className="search-input"
              placeholder="e.g., 'fuego', 'chavos', 'culcul'"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
            />
          </div>

          <div className="search-filters">
            <select
              value={searchType}
              onChange={(e) => setSearchType(e.target.value)}
            >
              <option value="partial">Partial match (recommended)</option>
              <option value="exact">Exact term only</option>
              <option value="contains">Search in definitions</option>
            </select>

            <select
              value={sourceFilter}
              onChange={(e) => setSourceFilter(e.target.value)}
            >
              <option value="all">All sources</option>
              <option value="tesoro">Tesoro (Dictionary)</option>
              <option value="dialecto">Dialecto (Cultural)</option>
              <option value="overlap">Overlapping terms</option>
            </select>
          </div>

          <div className="search-controls">
            <button className="btn btn-primary" onClick={handleSearch} disabled={loading}>
              <i className="fas fa-search"></i> {loading ? 'Searching...' : 'Search'}
            </button>
            <button className="btn btn-secondary" onClick={handleClear}>
              <i className="fas fa-eraser"></i> Clear
            </button>
          </div>
        </div>

        {/* Results Summary */}
        <div className="results-summary">
          <strong>Found {results.length} results</strong>
          {searchQuery && ` for "${searchQuery}"`}
          {sourceFilter !== 'all' && ` in ${sourceFilter} source`}
        </div>

        {/* Results Display */}
        <div className="results-container">
          {results.length === 0 ? (
            <div className="no-results">
              <h3>🔍 No results found</h3>
              <p>Try adjusting your search query or search type.</p>
            </div>
          ) : (
            results.map((item, index) => createDefinitionCard(item, index))
          )}
        </div>

        {/* Stats Summary */}
        <div className="results-summary">
          <small>
            📊 Dataset Stats: {stats.total} total entries
            • {stats.tesoro} from Tesoro
            • {stats.dialecto} from Dialecto
          </small>
        </div>
      </div>
    </div>
  );
};

export default LanguagePage;
